        String csv = new TourismTaxReport(store).generate(YearMonth.of(2027, 5));

        // 1 guest x 2 nights = 9.00
        assertEquals("""
                Pousada Maré Alta,tourism-tax,2027-05
                reservation,room,check_in,check_out,guests,nights,tax
